var mockHandlers = {
  getMenu: function () { return Promise.resolve(MOCK_MENU) },
  createOrder: function (data) {
    return Promise.resolve({
      orderId: 'ORD' + Date.now(),
      orderNo: 'F' + (Date.now() + '').slice(-8),
      items: data.items || [],
      totalPrice: data.totalPrice || 0,
      remark: data.remark || '',
      status: 'paid',
      createTime: new Date().toISOString(),
    })
  },
  getOrder: function (data) {
    return Promise.resolve({
      orderId: data.orderId || 'ORD000001',
      orderNo: 'F00000001',
      items: [],
      totalPrice: 0,
      remark: '',
      status: 'paid',
      createTime: new Date().toISOString(),
    })
  },
  getOrders: function () {
    // 从本地缓存读取已保存的订单
    var orders = []
    try { orders = wx.getStorageSync('ORDER_HISTORY_CACHE') || [] } catch (e) {}
    return Promise.resolve({ orders: orders })
  },
}

// ======== 公开 API ========

/**
 * 执行 mock 操作（对应之前的云函数名）
 */
function callCloud(name, data) {
  data = data || {}
  console.log('[Mock] ' + name)
  var handler = mockHandlers[name]
  return handler ? handler(data) : Promise.reject(new Error('未找到: ' + name))
}

/**
 * 带加载提示的调用
 */
function callCloudWithLoading(name, data, loadingText) {
  data = data || {}
  loadingText = loadingText || '加载中...'
  wx.showLoading({ title: loadingText, mask: true })
  return callCloud(name, data).then(function (result) {
    wx.hideLoading()
    return result
  }).catch(function (err) {
    wx.hideLoading()
    throw err
  })
}

module.exports = {
  callCloud: callCloud,
  callCloudWithLoading: callCloudWithLoading,
  USE_API: USE_API,
}
